/**
 * Where a just-uploaded job-builder document actually lives on S3.
 *
 * The rep's device never knows this: `filePath` and `bucketName` are generated by
 * the server when it files the document (`job-builder-docs/{company}/{lead}/
 * downPaymentReceipts/{ts}-{n}-document.pdf`), so the only way to name the document
 * a rep just uploaded is to read the stored row back. These helpers do that read
 * from whichever shape is to hand — the submit response, or the refetched lead —
 * without either caller having to know the other's shape.
 *
 * Pure and RN-free on purpose (same reason as `utils/addendum-drafts.ts`): the one
 * consumer, `widgets/components/LeadCenter/JobDocsSection.tsx`, pulls in React
 * Native and is untestable under jest here.
 */

export interface DocumentRef {
  filePath: string;
  bucketName: string;
}

/**
 * Bags that hold `{ agreements, orderSheets, downPaymentReceipt }` lists. A lead
 * carries `jobBuilderDocuments` (where a scanned/uploaded document lands);
 * `leadOutcomeDocuments` is the same shape on an outcome read.
 */
const DOCUMENT_BAGS = ['jobBuilderDocuments', 'leadOutcomeDocuments', 'documents'];

/**
 * Every plausible root of a document bag, innermost first.
 *
 * A lead object is its own root; an axios response nests the body under `data` and
 * the payload under `data.data`, and either may wrap the record as `lead`/`outcome`.
 * Walking a fixed list beats guessing, and an unrecognised shape simply yields `[]`
 * — the caller then falls back rather than logging a wrong path.
 */
const rootsOf = (source: any): any[] => [
  source,
  source?.data,
  source?.data?.data,
  source?.lead,
  source?.data?.lead,
  source?.data?.data?.lead,
  source?.outcome,
  source?.data?.outcome,
  source?.data?.data?.outcome,
];

/**
 * The rows of one document group (`downPaymentReceipt`, `agreements`, …) out of a
 * lead record or an API response. Returns `[]` when the source holds no such group.
 */
export const readDocumentGroup = (source: any, group: string): any[] => {
  if (!source || typeof source !== 'object') return [];
  for (const root of rootsOf(source)) {
    if (!root || typeof root !== 'object' || Array.isArray(root)) continue;
    if (Array.isArray(root[group])) return root[group];
    for (const bagKey of DOCUMENT_BAGS) {
      const bag = root[bagKey];
      if (bag && typeof bag === 'object' && Array.isArray(bag[group])) return bag[group];
    }
  }
  return [];
};

/** A document row's identity. `_id` is what the server assigns; `id` is a fallback. */
export const documentRowId = (row: any): string => String(row?._id ?? row?.id ?? '');

export const collectDocumentIds = (rows: any[]): Set<string> => {
  const ids = new Set<string>();
  (rows || []).forEach((row) => {
    const id = documentRowId(row);
    if (id) ids.add(id);
  });
  return ids;
};

/**
 * The rows that were NOT already on the lead — i.e. what this upload added.
 *
 * Diffing by id rather than by count is what makes the caller's two read paths
 * interchangeable: the submit response may return the whole group or only the new
 * rows, and either way the unknown ids are the answer. A row with no id is treated
 * as new, since it cannot be matched against the known set.
 */
export const pickNewDocuments = (knownIds: Set<string>, rows: any[]): any[] =>
  (rows || []).filter((row) => {
    if (!row || typeof row !== 'object') return false;
    const id = documentRowId(row);
    return !id || !knownIds.has(id);
  });

/**
 * Narrow document rows to the pair the portal needs to resolve them. A row with no
 * `filePath` is dropped — it names nothing, and an empty path in the log reads as a
 * document that cannot be opened.
 */
export const toDocumentRefs = (rows: any[]): DocumentRef[] =>
  (rows || [])
    .filter((row) => row && typeof row === 'object' && row.filePath)
    .map((row) => ({
      filePath: String(row.filePath),
      bucketName: String(row.bucketName || ''),
    }));
